const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const wuhanDistricts = ee.FeatureCollection('projects/sat-io/open-datasets/geospatial-boundary-data/wuhan_district_boundaries');
  const jianghan = wuhanDistricts.filter(ee.Filter.eq('NAME', 'Jianghan Qu'));

  if (jianghan.size().getInfo() === 0) {
    console.log("Could not find 'Jianghan Qu' in the district boundaries collection.");
    console.log("D"); // Indicates a data or naming issue
    return;
  }

  const geometry = jianghan.geometry();

  // Define comparison dates and a small window around them to increase data availability
  const date1_start = '2020-01-17'; // Jan 19, 2020 +/- 2 days
  const date1_end = '2020-01-21';
  const date2_start = '2020-02-02'; // Feb 4, 2020 +/- 2 days
  const date2_end = '2020-02-06';

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('NOAA/VIIRS/DNB/VCMCFG');

  // Function to process a given date range
  const processDateRange = (startDate, endDate, geom, tag) => {
    let col = collection.filterDate(startDate, endDate)
                       .filterBounds(geom);

    if (col.size().getInfo() === 0) {
      console.log(`No images found for ${tag} period.`);
      return { mean_rad: null, pixel_count: 0, image_count: 0 };
    }

    // Cloud mask: select pixels with good cloud-free coverage (e.g., >80%)
    col = col.map(image => image.updateMask(image.select('cf_cvg').gt(80)));

    const imageCount = col.size().getInfo();
    if (imageCount === 0) {
      console.log(`No images with sufficient cloud-free coverage for ${tag} period.`);
      return { mean_rad: null, pixel_count: 0, image_count: 0 };
    }

    // Take the mean of 'avg_rad' band over the collection for the period
    const composite = col.select('avg_rad').mean();

    // Calculate mean intensity and valid pixel count
    const stats = composite.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geom,
      scale: 750, // VIIRS DNB nominal resolution is ~750m
      maxPixels: 1e9
    });

    const meanRad = stats.get('avg_rad').getInfo();
    const pixelCount = stats.get('avg_rad_count').getInfo();

    return { mean_rad: meanRad, pixel_count: pixelCount, image_count: imageCount };
  };

  const stats1 = processDateRange(date1_start, date1_end, geometry, 'Jan 19');
  const stats2 = processDateRange(date2_start, date2_end, geometry, 'Feb 4');

  // Check for C1: Empty Collection
  if (stats1.image_count === 0 || stats2.image_count === 0) {
    console.log("C1");
    return;
  }

  // Check for C2: No Valid Pixels
  if (stats1.pixel_count === 0 || stats2.pixel_count === 0) {
    console.log(`Jan 19 Pixels: ${stats1.pixel_count}, Feb 4 Pixels: ${stats2.pixel_count}`);
    console.log("C2");
    return;
  }

  // Check for C3: Calculation Failure (None/NaN)
  if (stats1.mean_rad === null || isNaN(stats1.mean_rad) ||
      stats2.mean_rad === null || isNaN(stats2.mean_rad)) {
    console.log("Mean radiance calculation failed for one or both periods.");
    console.log("C3");
    return;
  }

  // 4. Calculation & 5. Validation & Final Answer
  const meanRad1 = stats1.mean_rad;
  const meanRad2 = stats2.mean_rad;

  console.log(`Jan 19 (Mean Rad): ${meanRad1.toFixed(4)}, Pixels: ${stats1.pixel_count}, Images: ${stats1.image_count}`);
  console.log(`Feb 4 (Mean Rad): ${meanRad2.toFixed(4)}, Pixels: ${stats2.pixel_count}, Images: ${stats2.image_count}`);

  if (meanRad2 < meanRad1) {
    console.log("A"); // Yes, Feb 4 was lower
  } else {
    console.log("B"); // No, Feb 4 was not lower or was equal
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
